public int longestValidParentheses(String s) {
    int[] dp = new int[s.length()];
    int max = 0;
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == ')') {
            if (i > 0 && s.charAt(i - 1) == '(') {
                dp[i] = i > 1 ? dp[i - 2] + 2 : 2;
            } else if (i > 0 && s.charAt(i - 1) == ')') {
                int j = i - dp[i - 1] - 1;
                if (j >= 0 && s.charAt(j) == '(') {
                    dp[i] = (j > 0 ? dp[j - 1] + 2 : 2) + dp[i - 1];
                }
            }
        }
        max = Math.max(max, dp[i]);
    }
    return max;
}

